=Laudo do Agente 1 (Triagem N1):
- Categoria: {{ $('Consultar Status Agente 1').last().json.result.category }}
- Severidade: {{ $('Consultar Status Agente 1').last().json.result.severity }}
- Requer escalonamento humano: {{ $('Consultar Status Agente 1').last().json.result.requires_human_escalation }}
- Acao recomendada: {{ $('Consultar Status Agente 1').last().json.result.recommended_action }}

Decida se o Agente 2 deve executar remediacao automatica.

parameters.jsCode:
const policies = {
  'Acessos/Senhas': { auto_remediation_allowed: true, allowed_action: 'UNLOCK_ACCOUNT' },
  'Redes/VPN': { auto_remediation_allowed: true, allowed_action: 'VPN_FAILOVER' },
  'Hardware': { auto_remediation_allowed: false, allowed_action: 'NONE', note: 'Exige atendimento presencial' },
  'Software': { auto_remediation_allowed: false, allowed_action: 'NONE' }
};
const key = Object.keys(policies).find(k => String(query).toLowerCase().includes(k.toLowerCase().split('/')[0]));
const policy = key ? { category: key, ...policies[key] } : { category: query, auto_remediation_allowed: false, allowed_action: 'NONE' };
policy.escalation_action = 'DISPATCH_INCIDENT';
policy.escalation_rule = 'Se o laudo exigir escalonamento humano, o Agente 2 deve ser acionado com DISPATCH_INCIDENT para abrir o incidente ITSM para a equipe N2, em qualquer categoria.';
return JSON.stringify(policy);

// Junta tudo: dados do chamado + Merge (respostas dos 2 agentes) + SLA do sub-workflow
const ticket = $('Normalizar Chamado').first().json;
const merged = $('Merge: Respostas dos 2 Agentes').first().json;
const result = {
  ticket_id: ticket.ticket_id,
  session_id: ticket.session_id,
  triage_n1: merged.triage_n1 ?? null,
  supervisor_decision: merged.supervisor_decision ?? null,
  remediation_n2: merged.remediation_n2 ?? null,
  agent1_task_id: merged.agent1_task_id ?? null,
  agent2_task_id: merged.agent2_task_id || null,
  subworkflow_sla: $input.first().json
};
return [{ json: { ticket_id: ticket.ticket_id, result_json: JSON.stringify(result), completed_at: new Date().toISOString() } }];

// Converte as linhas key/value da Data Table helpdesk_config em um objeto de configuracao.
// Defaults garantem que o fluxo funcione mesmo se uma chave estiver ausente.
const cfg = { AGENT1_BASE_URL: 'http://local:8001', AGENT2_BASE_URL: 'http://local:8002', POLL_MAX_ATTEMPTS: '40', HTTP_TIMEOUT_MS: '15000' };
for (const item of $input.all()) {
  if (item.json.key && item.json.value !== undefined && item.json.value !== '') cfg[item.json.key] = String(item.json.value);
}
cfg.POLL_MAX_ATTEMPTS = Number(cfg.POLL_MAX_ATTEMPTS);
cfg.HTTP_TIMEOUT_MS = Number(cfg.HTTP_TIMEOUT_MS);
delete cfg.DISCORD_WEBHOOK_URL;
return [{ json: cfg }];
